async (page) => {
  const dns = require('dns').promises;
  const https = require('https');

  const hosts = ['google.com', 'cloudflare.com', 'github.com'];
  const dnsHosts = ['example.com', 'wikipedia.org', 'stackoverflow.com'];

  const results = { connectivity: {}, dns: {} };

  // Connectivity tests via HTTPS HEAD request (proxy for ping)
  for (const host of hosts) {
    const start = Date.now();
    try {
      await new Promise((resolve, reject) => {
        const req = https.request({ host, port: 443, method: 'HEAD', timeout: 5000 }, (res) => {
          res.on('data', () => {});
          res.on('end', resolve);
          resolve();
        });
        req.on('error', reject);
        req.on('timeout', () => { req.destroy(); reject(new Error('timeout')); });
        req.end();
      });
      const elapsed = Date.now() - start;
      // Also resolve IP
      const addrs = await dns.lookup(host, { all: true });
      results.connectivity[host] = { reachable: true, time_ms: elapsed, addresses: addrs };
    } catch (e) {
      results.connectivity[host] = { reachable: false, error: e.message };
    }
  }

  // DNS resolution
  for (const host of dnsHosts) {
    try {
      const a = await dns.resolve4(host).catch(() => []);
      const aaaa = await dns.resolve6(host).catch(() => []);
      results.dns[host] = { A: a, AAAA: aaaa };
    } catch (e) {
      results.dns[host] = { error: e.message };
    }
  }

  return JSON.stringify(results, null, 2);
}
